\title{The Absolute Square-Tensor Bound for Equiangular Lines,\\ with Application to the Angle $\arccos(1/3)$}
\author{Aristotle}
\date{2026-06-30}

\begin{document}
\maketitle

\begin{abstract}
A finite family of unit vectors $v_1,\dots,v_N$ in $\R^d$ is \emph{equiangular} with common angle parameter $\alpha$ if $|\inner{v_i}{v_j}| = \alpha$ for all $i \neq j$. We give a complete, self-contained proof of the \emph{absolute bound} $N \le d^2$, valid for every parameter $0 \le \alpha < 1$ and every dimension $d \ge 1$. The proof proceeds through the \emph{tensor-square lift} $v \mapsto v \otimes v$, which sends $\R^d$ into $\R^{d^2}$ and satisfies the key identity $\inner{u\otimes u}{v\otimes v} = \inner{u}{v}^2$. Under this lift the Gram matrix of an equiangular system becomes a \emph{constant-pattern} matrix with diagonal $1$ and off-diagonal $\alpha^2$. We prove an exact quadratic-form identity for constant-pattern matrices, deduce their positive definiteness whenever the off-diagonal lies in $[0,1)$, and conclude that the lifted vectors are linearly independent, forcing $N \le d^2$. We specialize to the angle $\arccos(\tfrac13)$, the case $k=2$ of Balla's conjecture, where the conjectured sharp bound is $\max\{28, 2(d-1)\}$, and we situate the absolute bound within this broader theory.
\end{abstract}

\section{Introduction}

\subsection{The problem}
Let $d \ge 1$. A set of lines through the origin of $\R^d$ is \emph{equiangular} if every pair of lines meets at the same angle. Choosing a unit direction vector on each line, and recalling that a line determines its direction only up to sign, equiangularity is most naturally phrased in terms of absolute inner products.

\begin{definition}[Equiangular system]
A finite family $v_1,\dots,v_N$ of unit vectors in $\R^d$ is \emph{equiangular with common angle parameter} $\alpha \in [0,1)$ if
\[ |\inner{v_i}{v_j}| = \alpha \qquad \text{for all } i \neq j. \]
The corresponding lines $\R v_i$ then pairwise meet at angle $\theta = \arccos(\alpha)$.
\end{definition}

Let $N_\alpha(d)$ denote the maximum number of vectors in such a system for fixed $\alpha$, and $N(d) = \sup_\alpha N_\alpha(d)$ the maximum over all angles.

\subsection{Two regimes}
There are two qualitatively different bounds. The \emph{absolute bound} is uniform in the angle: $N(d) \le d^2$ holds for all configurations simultaneously. The \emph{relative} and finer bounds show that for a fixed angle, $N_\alpha(d)$ grows only linearly in $d$ for large $d$. This paper gives a fully self-contained proof of the absolute bound $N \le d^2$ and explains how the angle $\arccos(\tfrac13)$ sits at the gateway to the linear regime through Balla's conjecture.

\subsection{Main results}
\begin{theorem}[Absolute square-tensor bound]\label{thm:A}
Let $v_1,\dots,v_N$ be unit vectors in $\R^d$, equiangular with common parameter $\alpha \in [0,1)$. Then $N \le d^2$.
\end{theorem}

\begin{theorem}[Specialization to $\arccos(1/3)$]\label{thm:B}
Let $v_1,\dots,v_N$ be unit vectors in $\R^d$ with $|\inner{v_i}{v_j}| = \tfrac13$ for all $i \neq j$. Then $N \le d^2$.
\end{theorem}

\section{Preliminaries}
We work in $\R^d$ with the standard inner product $\inner{x}{y} = \sum_{a=1}^d x_a y_a$ and norm $\|x\| = \inner{x}{x}^{1/2}$.

\begin{definition}[Gram matrix]
For vectors $w_1,\dots,w_N$ in an inner product space, the \emph{Gram matrix} is $G \in \R^{N\times N}$ with $G_{ij} = \inner{w_i}{w_j}$.
\end{definition}

\begin{lemma}[Gram quadratic form]\label{lem:gram}
For any $w_1,\dots,w_N$ and scalars $x_1,\dots,x_N$,
\[ \Big\langle \textstyle\sum_i x_i w_i,\ \sum_j x_j w_j\Big\rangle = \sum_{i,j} x_i\, G_{ij}\, x_j. \]
\end{lemma}
\begin{proof} Bilinearity of the inner product. \end{proof}

\begin{lemma}[Definiteness implies independence]\label{lem:indep}
If $\sum_{i,j} x_i G_{ij} x_j > 0$ for every nonzero $x \in \R^N$, then $w_1,\dots,w_N$ are linearly independent.
\end{lemma}
\begin{proof}
If $\sum_i x_i w_i = 0$, then by Lemma~\ref{lem:gram} the form at $x$ equals $\|\sum_i x_i w_i\|^2 = 0$, so strict positivity forces $x = 0$.
\end{proof}

\section{The tensor-square lift}

\begin{definition}[Tensor square]
For $v \in \R^d$, the \emph{tensor square} $v \otimes v \in \R^{d^2}$ is the vector whose coordinate indexed by $(a,b) \in \{1,\dots,d\}^2$ is $(v\otimes v)_{(a,b)} = v_a v_b$.
\end{definition}

\begin{theorem}[Tensor-square inner product]\label{thm:tsq}
For all $u,v \in \R^d$, $\ \inner{u\otimes u}{v\otimes v} = \inner{u}{v}^2$.
\end{theorem}
\begin{proof}
\[ \inner{u\otimes u}{v\otimes v} = \sum_{a,b}(u_a u_b)(v_a v_b) = \Big(\sum_a u_a v_a\Big)\Big(\sum_b u_b v_b\Big) = \inner{u}{v}^2. \qedhere \]
\end{proof}

\begin{corollary}[Norm]\label{cor:norm}
$\|v\otimes v\|^2 = \|v\|^4$; in particular $v\otimes v$ is a unit vector when $v$ is.
\end{corollary}

\begin{corollary}[Off-diagonal]\label{cor:off}
If $u,v$ are unit vectors with $|\inner{u}{v}| = \alpha$, then $\inner{u\otimes u}{v\otimes v} = \alpha^2$.
\end{corollary}
\begin{proof}
By Theorem~\ref{thm:tsq}, $\inner{u\otimes u}{v\otimes v} = \inner{u}{v}^2 = |\inner{u}{v}|^2 = \alpha^2$.
\end{proof}

\section{The constant-pattern engine and the bound}

\begin{definition}[Constant-pattern matrix]
A matrix $H \in \R^{N\times N}$ is \emph{constant-pattern with diagonal $1$ and off-diagonal $c$} if $H_{ii} = 1$ and $H_{ij} = c$ for $i \neq j$; equivalently $H = (1-c)I + cJ$ with $J$ the all-ones matrix.
\end{definition}

\begin{proposition}\label{prop:lifted}
Let $v_1,\dots,v_N$ be unit vectors in $\R^d$, equiangular with parameter $\alpha$. Set $w_i = v_i \otimes v_i \in \R^{d^2}$ with Gram matrix $H$. Then $H$ is constant-pattern with diagonal $1$ and off-diagonal $\alpha^2$.
\end{proposition}
\begin{proof}
Diagonal: $H_{ii} = \|w_i\|^2 = \|v_i\|^4 = 1$ by Corollary~\ref{cor:norm}. Off-diagonal: $H_{ij} = \alpha^2$ for $i \neq j$ by Corollary~\ref{cor:off}.
\end{proof}

\begin{theorem}[Quadratic-form identity]\label{thm:quad}
If $H$ is constant-pattern with diagonal $1$ and off-diagonal $c$, then for every $x \in \R^N$,
\[ \sum_{i,j} x_i\, H_{ij}\, x_j = (1-c)\sum_i x_i^2 + c\Big(\sum_i x_i\Big)^2. \]
\end{theorem}
\begin{proof}
Write $H_{ij} = c + (1-c)[i=j]$. Then $\sum_{i,j} x_i H_{ij} x_j = c\sum_{i,j} x_i x_j + (1-c)\sum_i x_i^2 = c(\sum_i x_i)^2 + (1-c)\sum_i x_i^2$.
\end{proof}

\begin{theorem}[Positive definiteness]\label{thm:posdef}
If $H$ is constant-pattern with diagonal $1$ and off-diagonal $c$ with $0 \le c < 1$, then $\sum_{i,j} x_i H_{ij} x_j > 0$ for every nonzero $x$.
\end{theorem}
\begin{proof}
By Theorem~\ref{thm:quad} the form equals $(1-c)\sum_i x_i^2 + c(\sum_i x_i)^2$. Since $1 - c > 0$ and $\sum_i x_i^2 > 0$ for $x \neq 0$, the first term is positive; since $c \ge 0$, the second is nonnegative.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:A}]
Form $w_i = v_i \otimes v_i \in \R^{d^2}$. By Proposition~\ref{prop:lifted} their Gram matrix is constant-pattern with off-diagonal $c = \alpha^2 \in [0,1)$. By Theorem~\ref{thm:posdef} the Gram quadratic form is strictly positive on nonzero vectors, so by Lemma~\ref{lem:indep} the $w_i$ are linearly independent in $\R^{d^2}$. Hence $N \le d^2$.
\end{proof}

\begin{proof}[Proof of Theorem~\ref{thm:B}]
Apply Theorem~\ref{thm:A} with $\alpha = \tfrac13 \in [0,1)$.
\end{proof}

\section{Sharpness and Balla's conjecture for $\arccos(1/3)$}

The absolute bound $N \le d^2$ is uniform across all angles and is essentially sharp in the complex setting: a system of $d^2$ complex equiangular lines (a SIC-POVM) is conjectured to exist in every complex dimension, achieving equality. Over the reals it is loose for large $d$ at any fixed angle, where the count grows only linearly. For the angle $\arccos(\tfrac{1}{2k-1})$ the theorem of Balla, Dr\"axler, Keevash, and Sudakov gives, for large $d$,
\[ N_{1/(2k-1)}(d) = \Big\lfloor \frac{k(d-1)}{k-1}\Big\rfloor, \]
with spectral-radius parameter $\kappa_1(k)$; for $k=2$, the angle $\arccos(\tfrac13)$, one has $\kappa_1 = 2$ (witnessed by $K_2$) and leading behavior $2(d-1)$.

\begin{conjecture}[Balla, case $\alpha = 1/3$]
For all $d \ge 1$, $\ N_{1/3}(d) \le \max\{28,\ 2(d-1)\}$.
\end{conjecture}

The constant $28$ is the small-dimension cap from the relevant extremal quantity at $\alpha = \tfrac13$; beyond the crossover the bound is the linear term $2(d-1)$. The absolute bound proved here is weaker than the conjecture for $d \ge 6$ but is unconditional and elementary, and is the structural backbone of the sharper spectral arguments. The same positive-definiteness toolkit underlies the relative bound
\[ N_\alpha(d) \le \frac{d(1-\alpha^2)}{1 - d\alpha^2} \qquad (d\alpha^2 < 1), \]
which improves on $d^2$ in the small-angle regime.

\section{Applications}
\textbf{Quantum information.} Maximal complex equiangular line systems (SIC-POVMs) furnish symmetric, informationally complete quantum measurements with $d^2$ outcomes. \textbf{Frame theory.} Equiangular tight frames yield optimal Grassmannian packings and good compressed-sensing matrices, with mutual coherence equal to $\alpha$. \textbf{Combinatorics.} The Gram sign pattern of a real equiangular system encodes a regular two-graph, linking the geometry to Seidel-matrix spectra and strongly regular graphs.

\section{Future directions}
\begin{enumerate}
\item Prove the relative bound $N \le d(1-\alpha^2)/(1-d\alpha^2)$ via ranks of perturbed pattern matrices.
\item Establish the $1/(2k-1)$ regime and the Balla--Dr\"axler--Keevash--Sudakov theorem.
\item Generalize the tensor square and constant-pattern engine to complex equiangular lines.
\item Complement the upper bound with explicit constructions witnessing equality $N = d^2$ in the complex case.
\item Develop the constant-pattern positive-definiteness lemmas as reusable statements about equicorrelated matrices.
\end{enumerate}

\section{Conclusion}
Any equiangular system of unit vectors in $\R^d$ has at most $d^2$ members, for every common angle. The proof rests on the tensor-square lift, which squares away the troublesome signs, and on the transparent structure of constant-pattern matrices, positive definite whenever the off-diagonal lies in $[0,1)$. Specialized to $\arccos(\tfrac13)$, this is the unconditional backbone beneath Balla's conjecture and its sharp linear ceiling $\max\{28, 2(d-1)\}$.

\end{document}

